head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF08305";
// 원본 : /etn/ULDSTF08305.gfm (ETN/ETF 투자유의종목 지정해제 팝업)
/*
 * 화면 동작
 *  - 부모(투자유의종목 마감 — AS-IS ULDSTF08306, TO-BE ULDSTF08200)가 넘긴 업무처리번호가 비면 신규, 있으면 상세를 조회해 수정 모드가 된다.
 *  - 신규는 [종목선택](ETN ULDSTF08045 / ETF ULDSTF08047)으로 종목을 여러 개 고를 수 있고, 종목마다 한 건씩 등록한다(중복 확인 → 확인 → 행별 register).
 *  - 수정·삭제도 그리드 행마다 한 건씩 보낸다(modify·remove). 삭제가 모두 성공하면 팝업을 닫고, 부모는 await 가 끝나면 목록을 다시 조회한다.
 *  - 조회기준일이 오늘보다 앞이면 조회 전용(버튼 모두 잠금)이다.
 *  - 공시안내문작성(ULDSTF92024)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #7).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08305/ULDSTF08305.md (§번호는 이 문서의 절)
 */

// 부모 화면에서 넘겨받는 값 (§1.2)
scwin.bzProcsNo = "";       // 업무처리번호 — 비면 신규, 있으면 수정. 그리드 행 클릭·저장 성공 때 바뀐다(AS-IS fr_bz_procs_no)
scwin.secugrpId = "";       // 증권그룹ID EN: ETN, EF: ETF
scwin.isuCd = "";           // 부모 목록에서 고른 종목코드 — 신규인데 값이 있으면 그리드 한 행으로 두고 종목선택을 잠근다
scwin.isuNm = "";           // 부모 목록에서 고른 종목명
scwin.isurCd = "";          // 발행기관코드 — 그리드 행 클릭 때 바뀐다(AS-IS Isur_cd)
scwin.designDd = "";        // 지정해제일 기본값 (신규)
scwin.inqDd = "";           // 조회기준일 — 오늘보다 앞이면 조회 전용, 중복 확인·저장 기준일(basDd)
scwin.fstDtectDd = "";      // 최초적출일 — 추가여부가 Y 가 아닌 종목의 최초지정일자

// 화면 상태값
scwin.todayDd = "";         // 서버 현재일 yyyyMMdd (AS-IS fn_todayDate 의 TODAY_DD)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.selectedRow = -1;     // 그리드에서 클릭한 행 (AS-IS selectedGrdNum, 1-base 0 = 미선택 → TO-BE -1)
scwin.dsclRow = -1;         // 공시안내문작성 대상 행 — 호환용 getPar 가 읽는다

// 고정값
scwin.DESIGN_CD = "05";                 // ETP투자유의지정코드 05: 지정해제 (AS-IS etp_Invstwarn_design_cd)
scwin.SECUGRP_ID_EN = "EN";             // 증권그룹 ETN (AS-IS SECUGRP_ID_EN)
scwin.SECUGRP_ID_EF = "EF";             // 증권그룹 ETF (AS-IS SECUGRP_ID_EF)
scwin.DSCL_FORM_CD = {                  // 공시안내문 서식코드 (AS-IS discls_form_cd)
    EN : "68392",                       // 상장지수증권 투자유의종목 지정해제 안내공시
    EF : "99358"                        // ETF 투자유의종목 지정해제
};
scwin.DSCL_MKT_ID = "1";                // 공시안내문 시장구분 (AS-IS arr[3] = '1' 고정)
scwin.ISU_GUBUN_ALL = "3";              // 종목선택 구분 3: 상장전체 (AS-IS fn_GetParIsu arr[1])
scwin.COMPLETE_YN_OK = "Y";             // 저장·삭제 응답 completeYn 의 성공 값 — TODO: 명세에 값이 없어 가정 (§10 #5)

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다. (AS-IS buttonSet.set*Info)
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08305.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 달력 바인딩 → 현재일 → 종목선택 잠금 → 모드 분기(신규 준비 / 상세 조회). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) 의 arr[0]~arr[8] (§1.2)
    const param = $c.data.getParameter() ?? {};

    scwin.isuCd = String(param.isuCd ?? "");               // AS-IS arr[0] Isu_cd
    scwin.isuNm = String(param.isuNm ?? "");               // AS-IS arr[1] Isu_nm
    scwin.secugrpId = String(param.secugrpId ?? "");       // AS-IS arr[2] Secugrp_id
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");       // AS-IS arr[4] fr_bz_procs_no
    scwin.designDd = String(param.designDd ?? "");         // AS-IS arr[5] design_dd
    scwin.inqDd = String(param.inqDd ?? "");               // AS-IS arr[6] Inq_dd
    scwin.fstDtectDd = String(param.fstDtectDd ?? "");     // AS-IS arr[7] fst_dtect_dd
    scwin.isurCd = String(param.isurCd ?? "");             // AS-IS arr[8] Isur_cd
    // AS-IS arr[3] Mkt_id 는 받기만 하고 쓰지 않아 옮기지 않는다(§8 #9).

    // 3) 달력 검사 바인딩(1회) — 단일 달력 (규칙 37)
    $c.date.checkCalendarFormat(edt_DesignDd, "yyyyMMdd");

    // 4) 서버 현재일 — 원본 fn_todayDate(동기 조회 TODAY_DD)는 명세에 없어 gcc 로 대체 (§5.7)
    scwin.todayDd = $c.date.getServerDateTime();

    // 5) 종목선택 잠금 — 원본 fn_SetIsuCdBtnShow (§6.2)
    scwin.setIsuBtnState();

    // 6) 모드 분기 — 원본 fn_onload + dts_Mst OnLoadCompleted
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initNewForm();
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }

    await scwin.selectOne();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목선택 버튼 클릭 (§6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08305.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_isuList_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목 그리드 셀 클릭 — 안내문작성 대상 행을 고른다. (원본 grid_1 OnClick — §6.4)
 * @param {Number} row 행 index
 * @param {Number} col 열 index
 * @param {String} colId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_isuList_oncellclick = async function (row, col, colId) {
    try {
        scwin.selectGridRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08305.grd_isuList_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08305.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08305.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08305.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08305.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상세 조회. 업무처리번호로 지정해제 내역을 받아 입력 폼과 그리드 한 행에 채우고, 조회기준일로 버튼 상태를 정한다.
 * (원본 fn_onload 수정 분기 + dts_Mst OnLoadCompleted — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectOne = async function () {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/etn/invstwarn/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    const requestData = {
        secugrpId : scwin.secugrpId,        // 증권그룹ID (AS-IS SECUGRP_ID)
        bzProcsNo : scwin.bzProcsNo         // 업무처리번호 (AS-IS BZ_PROCS_NO)
    };

    dma_detail.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패면 버튼은 잠긴 채로 둔다(init 1단계) — 통신 오류 안내는 공통 오류 핸들러가 한다.
    if (!result.responseJSON?.success) return;

    // AS-IS CopyDataSet(dts_Mst, dts_Isu_Temp) — 조회한 종목을 그리드 한 행으로 둔다(수정·삭제가 행 단위로 돈다).
    const detail = dma_detail.getJSON();
    dlt_isuList.setJSON([{
        bzProcsNo : detail.bzProcsNo ?? "",
        isuCd : detail.isuCd ?? "",
        isuNm : detail.isuNm ?? "",
        isurCd : detail.isurCd ?? "",
        comNm : "",                         // TODO: 명세 select-one 응답에 발행기관명이 없음 (§10 #6)
        addYn : detail.addYn ?? "",
        status : ""
    }]);
    scwin.selectedRow = -1;

    // AS-IS Isur_cd·fr_bz_procs_no = dts_Isu_Temp 1행
    scwin.isurCd = detail.isurCd ?? "";
    scwin.bzProcsNo = detail.bzProcsNo || scwin.bzProcsNo;

    scwin.setIsuBtnState();

    // 조회기준일이 오늘보다 앞이면 조회 전용 — 원본 문자열 비교 그대로(조회기준일이 비면 조회 전용, §8 #8)
    if (scwin.inqDd < scwin.todayDd) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    } else {
        $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
    }
};

/**
 * @method
 * @name scwin.checkDuplicate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 종목마다 같은 기준일에 이미 지정해제가 저장돼 있는지 확인한다. 하나라도 중복이면 안내한다.
 * (원본 fn_duplicate_check — §5.2)
 * @returns {Promise<Boolean|null>} 중복(또는 확인 실패)이면 true, 없으면 false, 중복 실행으로 건너뛰면 null
 * @hidden N
 */
scwin.checkDuplicate = async function () {
    const sbmOptions = {
        id : "sbm_checkDuplicate",
        method : "get",
        action : "/api/listing/lstproc/etn/invstwarn/select-check-duplicate",
        isProcessMsg : false
    };

    const rowCount = dlt_isuList.getRowCount();

    for (let i = 0; i < rowCount; i++) {
        const requestData = {
            etpInvstwarnDesignCd : scwin.DESIGN_CD,             // ETP투자유의지정코드 05
            basDd : scwin.inqDd,                                // 기준일자 (AS-IS Inq_dd)
            isuCd : dlt_isuList.getCellData(i, "isuCd")         // 종목코드
        };

        const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
        if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

        // 확인하지 못했으면 저장하지 않는다(※TO-BE — 원본은 오류 안내 뒤 빈 값으로 통과, §8 #6).
        if (!result.responseJSON?.success) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "중복확인"));
            return true;
        }

        // TODO: 명세는 result.responseJSON.dupChk 로 적었다 — body 아래인지 확인 (§10 #4). 지금은 둘 다 받는다.
        if (scwin.getResBody(result)?.dupChk === "Y") {
            await $c.win.alert("중복된 종목이 저장되어 있습니다.");
            return true;
        }
    }

    return false;
};

/**
 * @method
 * @name scwin.selectFstDesignDd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목의 최초지정일자를 조회한다. (원본 fn_Instwarn_fstdd 의 동기 조회 — §5.3)
 * @param {String} isuCd 종목코드
 * @returns {Promise<String|null>} 최초지정일자(없거나 실패면 ""), 중복 실행으로 건너뛰면 null
 * @hidden N
 */
scwin.selectFstDesignDd = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectFstDesignDd",
        method : "get",
        action : "/api/listing/lstproc/etn/invstwarn/select-fst-design-dd",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) return "";

    // TODO: 명세는 result.responseJSON.fstDesignDd 로 적었다 — body 아래인지 확인 (§10 #4). 지금은 둘 다 받는다.
    return String(scwin.getResBody(result)?.fstDesignDd ?? "");
};

/**
 * @method
 * @name scwin.registerRow
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 한 행을 등록한다. 명세 register 의 isuList 에 이 행 하나만 담아 보내고(최초지정일자가 종목마다 달라서),
 * 서버가 채번한 업무처리번호를 그 행에 남긴다. (원본 fn_save 의 행별 fn_copy_dts + fn_save_trs(TRS_IDX_INSERT) — §5.4)
 * @param {Number} row 그리드 행 index
 * @returns {Promise<Boolean|null>} 성공 여부, 중복 실행으로 건너뛰면 null
 * @hidden N
 */
scwin.registerRow = async function (row) {
    const isu = dlt_isuList.getRowJSON(row);

    const fstDesignDd = await scwin.getFstDesignDd(isu);
    if (fstDesignDd === null) return null;

    // 전문 머리 — 지정해제일·사유·투자유의사항·기타는 입력 폼(dma_detail) 값
    dma_register.setEmptyValue();
    dma_register.set("secugrpId", scwin.secugrpId);                 // LIST_BZ_TP_CD 716/750 은 서버가 정함(명세)
    dma_register.set("etpInvstwarnDesignCd", scwin.DESIGN_CD);
    dma_register.set("designDd", dma_detail.get("designDd"));
    dma_register.set("designRsn", dma_detail.get("designRsn"));
    dma_register.set("etpInvstwarnContn", dma_detail.get("etpInvstwarnContn"));
    dma_register.set("misc", dma_detail.get("misc"));
    dma_register.set("basDd", scwin.inqDd);
    dma_register.set("fstDesignDd", fstDesignDd);

    // 종목 목록 — 업무처리번호를 비워 서버 채번 (명세 "비우면 서버 채번", AS-IS 화면 채번 fn_getNewBzProcNo 대체)
    dlt_register.setJSON([{
        bzProcsNo : "",
        isuCd : isu.isuCd ?? "",
        isurCd : isu.isurCd ?? "",
        addYn : isu.addYn ?? ""
    }]);

    const sbmOptions = {
        id : "sbm_registerRow",
        method : "post",
        action : "/api/listing/lstproc/etn/invstwarn/register",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const requestData = {
        ...dma_register.getJSON(),
        isuList : dlt_register.getAllJSON()     // 등록 종목 목록 (AS-IS dts_Isu_Temp 의 한 행)
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!scwin.isSaveSuccess(result)) return false;

    // 성공한 행에만 번호를 남긴다 — 실패한 행에 번호가 남으면 재시도 때 수정 건으로 오판한다.
    dlt_isuList.setCellData(row, "bzProcsNo", scwin.getRegisteredNo(result));
    return true;
};

/**
 * @method
 * @name scwin.modifyRow
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 한 행을 수정한다. (원본 fn_update 의 행별 fn_copy_dts + fn_save_trs(TRS_IDX_UPDATE) — §5.5)
 * @param {Number} row 그리드 행 index
 * @returns {Promise<Boolean|null>} 성공 여부, 중복 실행으로 건너뛰면 null
 * @hidden N
 */
scwin.modifyRow = async function (row) {
    const isu = dlt_isuList.getRowJSON(row);

    const fstDesignDd = await scwin.getFstDesignDd(isu);
    if (fstDesignDd === null) return null;

    dma_update.setEmptyValue();
    dma_update.set("bzProcsNo", isu.bzProcsNo ?? "");
    dma_update.set("secugrpId", scwin.secugrpId);
    dma_update.set("isuCd", isu.isuCd ?? "");
    dma_update.set("isurCd", isu.isurCd ?? "");
    dma_update.set("designDd", dma_detail.get("designDd"));
    dma_update.set("designRsn", dma_detail.get("designRsn"));
    dma_update.set("etpInvstwarnContn", dma_detail.get("etpInvstwarnContn"));
    dma_update.set("misc", dma_detail.get("misc"));
    dma_update.set("addYn", isu.addYn ?? "");
    dma_update.set("basDd", scwin.inqDd);
    dma_update.set("etpInvstwarnDesignCd", scwin.DESIGN_CD);
    dma_update.set("fstDesignDd", fstDesignDd);

    const sbmOptions = {
        id : "sbm_modifyRow",
        method : "post",
        action : "/api/listing/lstproc/etn/invstwarn/modify",
        ref : "dma_update",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    return scwin.isSaveSuccess(result);
};

/**
 * @method
 * @name scwin.removeRow
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 한 행을 삭제한다. (원본 fn_delete 의 행별 fn_copy_dts + fn_save_trs(TRS_IDX_DELETE) — §5.6)
 * @param {Number} row 그리드 행 index
 * @returns {Promise<Boolean|null>} 성공 여부, 중복 실행으로 건너뛰면 null
 * @hidden N
 */
scwin.removeRow = async function (row) {
    const isu = dlt_isuList.getRowJSON(row);

    dma_delete.setEmptyValue();
    dma_delete.set("bzProcsNo", isu.bzProcsNo ?? "");
    dma_delete.set("secugrpId", scwin.secugrpId);
    dma_delete.set("isuCd", isu.isuCd ?? "");
    dma_delete.set("isurCd", isu.isurCd ?? "");

    const sbmOptions = {
        id : "sbm_removeRow",
        method : "post",
        action : "/api/listing/lstproc/etn/invstwarn/remove",
        ref : "dma_delete",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    return scwin.isSaveSuccess(result);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 폼 준비. 지정해제일은 부모가 넘긴 값, 사유·투자유의사항·기타는 표준 문구를 넣고,
 * 부모가 종목을 넘겼으면 그 종목을 그리드 한 행으로 둔다. 통신 없음. (원본 fn_onload 신규 분기 + dts_Mst·dts_Isu_Temp OnLoadCompleted — §6.1)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_detail.setEmptyValue();
    dma_detail.set("designDd", scwin.designDd);
    dma_detail.set("designRsn", "투자유의종목 지정단위기간(3매매거래일) 종료");
    dma_detail.set("etpInvstwarnContn", "지정해제일부터 투자유의종목 지정을 해제하며, 접속매매의 매매거래방식이 적용됩니다.");
    dma_detail.set("misc", "-");

    dlt_isuList.removeAll();
    scwin.selectedRow = -1;

    if (!$c.util.isEmpty(scwin.isuCd)) {
        dlt_isuList.setJSON([{
            bzProcsNo : "",
            isuCd : scwin.isuCd,
            isuNm : scwin.isuNm,
            isurCd : scwin.isurCd,
            comNm : "",
            addYn : "",                 // 부모가 넘긴 종목 — 최초지정일자는 최초적출일(fstDtectDd)
            status : ""
        }]);
    }
};

/**
 * @method
 * @name scwin.setIsuBtnState
 * @author Inswave
 * @date 2026. 10. 28
 * @description [종목선택] 잠금. 업무처리번호가 있거나(수정·저장 후) 부모가 종목을 넘겼으면 잠근다. (원본 fn_SetIsuCdBtnShow — §6.2)
 * @returns
 * @hidden N
 */
scwin.setIsuBtnState = function () {
    const locked = !$c.util.isEmpty(scwin.bzProcsNo) || !$c.util.isEmpty(scwin.isuCd);
    img_SetIsuCd.setDisabled(locked);
};

/**
 * @method
 * @name scwin.selectGridRow
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 행 선택 — 선택 행·발행기관코드·업무처리번호를 화면 상태값에 둔다. (원본 fn_SelectGridRow — §6.4)
 * @param {Number} row 그리드 행 index
 * @returns
 * @hidden N
 */
scwin.selectGridRow = function (row) {
    if (row < 0 || row >= dlt_isuList.getRowCount()) return;

    scwin.selectedRow = row;
    scwin.isurCd = dlt_isuList.getCellData(row, "isurCd");
    scwin.bzProcsNo = dlt_isuList.getCellData(row, "bzProcsNo");
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목선택. ETN 은 ULDSTF08045, ETF 는 ULDSTF08047 을 열어 고른 종목 목록으로 그리드를 바꾼다. 고른 종목은 모두 추가여부 Y.
 * 취소·닫기(X)는 배열이 아닌 { isCloseButtonClick } 객체가 오므로 배열 여부로 판정한다.
 * (원본 img_SetIsuCd onclick + fn_GetParIsu + fn_SetParIsu + fn_PopFindEtnCode/fn_PopFindEtfCode — §6.3)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    let popupId = "";
    if (scwin.secugrpId === scwin.SECUGRP_ID_EN) {
        popupId = "ULDSTF08045";
    } else if (scwin.secugrpId === scwin.SECUGRP_ID_EF) {
        popupId = "ULDSTF08047";
    } else {
        return;     // 원본도 EN·EF 외에는 아무것도 하지 않는다
    }

    // AS-IS fn_GetParIsu — arr[0] "", arr[1] "3"(상장전체), CopyDataSet(dts_Isu_Temp, param_dts)
    // TODO: isuList(이미 고른 종목)는 08045 전환본이 받지 않는다, 08047 은 전환본이 없다 — 경로·키 확인 (§10 #8)
    const data = {
        isurCd : "",
        gubun : scwin.ISU_GUBUN_ALL,
        isuList : dlt_isuList.getAllJSON()
    };
    const options = {
        id : popupId,
        popupName : "종목선택",
        width : 800,
        height : 650,
        frameModal : "top",
        type : "pageFramePopup"
    };

    const result = await $c.win.openPopup("/ui/lst/common/" + popupId + ".xml", options, data);

    // [확인]은 고른 종목 배열을 돌려준다. 취소·닫기(X)·ESC 는 { isCloseButtonClick } 객체다.
    if (!Array.isArray(result) || result.length === 0) return;

    // AS-IS fn_SetParIsu — 받은 목록으로 통째로 바꾸고 모든 행 ADD_YN = "Y"
    dlt_isuList.setJSON(result.map(isu => ({
        bzProcsNo : "",
        isuCd : isu.isuCd ?? "",
        isuNm : isu.isuNm ?? "",
        isurCd : isu.isurCd ?? "",
        comNm : isu.comNm ?? "",
        addYn : "Y",
        status : ""
    })));
    scwin.selectedRow = -1;     // ※TO-BE — 목록이 바뀌면 이전 선택 행을 지운다(§8 #10)
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장·수정 전 입력 검증. 종목 행 유무 → 지정해제일 필수·날짜 형식(공통 검증). (원본 fn_CheckForm — §6.5)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if (dlt_isuList.getRowCount() === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }

    // 실패 시 표준 안내와 포커스는 공통이 처리한다(규칙 24).
    const options = {
        validateType : "alert",
        checkType : "single",
        fields : {
            edt_DesignDd : { required : true, format : "date", name : "지정해제일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, options)) return false;

    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 저장. 검증 → 종목 중복 확인 → 저장 확인 → 행별 등록 순서 (원본 fn_save — §6.6, §1.4 업무 4)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // 중복(또는 확인 실패)이면 멈춘다. null 은 중복 실행으로 건너뜀.
    if (await scwin.checkDuplicate() !== false) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정. 검증 → 수정 확인 → 행별 수정 순서 (원본 fn_update — §6.7, §1.4 업무 5)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제. 삭제 확인 → 행별 삭제 순서. 입력 검증은 하지 않는다. (원본 fn_delete — §6.8, §1.4 업무 6)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // ※TO-BE — 원본은 행이 없으면 확인만 받고 아무것도 하지 않았다(§8 #11).
    if (dlt_isuList.getRowCount() === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.processRows
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 종목을 한 건씩 순차 전송하고 결과를 안내한 뒤 화면 상태를 맞춘다. (원본 행 루프 + trs OnSuccess/OnFail — §6.9)
 *  - 행마다 status 에 Y/N 을 남긴다. 한 건이라도 실패하면 MSG-A002, 삭제는 성공한 행을 그리드에서 지운다.
 *  - 모두 성공하면 MSG-A001. 삭제는 팝업을 닫고, 저장은 수정 모드로 바꾸고 종목선택을 잠근다.
 *  - 부모 목록은 팝업이 닫힌 뒤 부모가 다시 조회한다(원본 fn_parentRefresh 대체, §8 #12).
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @returns
 * @hidden N
 */
scwin.processRows = async function (trJob) {
    const jobNm = { I : "저장", U : "수정", D : "삭제" }[trJob];
    const rowCount = dlt_isuList.getRowCount();
    let errCnt = 0;

    for (let i = 0; i < rowCount; i++) {
        let ok;
        if (trJob === "I") {
            ok = await scwin.registerRow(i);
        } else if (trJob === "U") {
            ok = await scwin.modifyRow(i);
        } else {
            ok = await scwin.removeRow(i);
        }
        if (ok === null) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

        dlt_isuList.setCellData(i, "status", ok ? "Y" : "N");
        if (!ok) errCnt++;
    }

    if (errCnt > 0) {
        // "[^] 처리 실패하였습니다." — 어느 행인지는 status 로 남는다. 저장은 신규 상태 그대로(재시도 가능).
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));

        // 삭제는 성공한 행을 지워 실패한 행만 남긴다. 뒤에서부터 지워야 index 가 밀리지 않는다(§8 #4).
        if (trJob === "D") {
            for (let i = dlt_isuList.getRowCount() - 1; i >= 0; i--) {
                if (dlt_isuList.getCellData(i, "status") === "Y") dlt_isuList.removeRow(i);
            }
            scwin.selectedRow = -1;
        }
        return;
    }

    // "[^] 처리 성공하였습니다."
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    if (trJob === "D") {
        $c.win.closePopup();
        return;
    }

    // 저장은 마지막 행의 업무처리번호가 화면 상태값이 된다(원본 fr_bz_procs_no). 한 건이면 그 행을 고른다.
    if (trJob === "I") scwin.bzProcsNo = dlt_isuList.getCellData(rowCount - 1, "bzProcsNo");
    if (rowCount === 1) scwin.selectGridRow(0);

    if (trJob === "I") {
        $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
        scwin.setIsuBtnState();
    }
};

/**
 * @method
 * @name scwin.getFstDesignDd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 전송할 최초지정일자. 추가여부 Y(종목선택으로 고른 종목)면 서버 최초지정일자, 없으면 지정해제일이고,
 * 그 밖(부모가 넘긴·조회한 종목)은 최초적출일이다. (원본 fn_save_trs 분기 + fn_Instwarn_fstdd — §6.10)
 * @param {Object} isu 그리드 행 (isuCd·addYn)
 * @returns {Promise<String|null>} 최초지정일자, 중복 실행으로 건너뛰면 null
 * @hidden N
 */
scwin.getFstDesignDd = async function (isu) {
    if (isu.addYn !== "Y") return scwin.fstDtectDd;

    const fstDesignDd = await scwin.selectFstDesignDd(isu.isuCd ?? "");
    if (fstDesignDd === null) return null;

    return $c.util.isEmpty(fstDesignDd) ? dma_detail.get("designDd") : fstDesignDd;
};

/**
 * @method
 * @name scwin.getResBody
 * @author Inswave
 * @date 2026. 10. 28
 * @description target 없이 부른 조회의 응답 본문. 명세는 responseJSON 바로 아래 키로 적었고 다른 API 는 body 아래라 둘 다 받는다. (§10 #4)
 * @param {Object} result executeDynamic 결과
 * @returns {Object} 응답 본문 (없으면 빈 객체)
 * @hidden N
 */
scwin.getResBody = function (result) {
    const res = result?.responseJSON ?? {};
    const body = res.body;
    return (body !== null && typeof body === "object") ? body : res;
};

/**
 * @method
 * @name scwin.isSaveSuccess
 * @author Inswave
 * @date 2026. 10. 28
 * @description 등록·수정·삭제 응답 판정 — success 이고 completeYn 이 성공 값이면 true. (§5.4~5.6)
 * @param {Object} result executeDynamic 결과
 * @returns {Boolean} 성공 여부
 * @hidden N
 */
scwin.isSaveSuccess = function (result) {
    // TODO: completeYn 의 성공 값("Y")은 가정 — 명세 확인 필요 (§10 #5)
    return result.responseJSON?.success === true && dma_resultSave.get("completeYn") === scwin.COMPLETE_YN_OK;
};

/**
 * @method
 * @name scwin.getRegisteredNo
 * @author Inswave
 * @date 2026. 10. 28
 * @description 등록 응답의 업무처리번호. 한 행씩 보내므로 bzProcsNoList 의 첫 값이고, 없으면 bzProcsNo 다. (§5.4)
 * bzProcsNoList 가 배열인지 쉼표 문자열인지 명세에 없어 둘 다 받는다(§10 #3).
 * @param {Object} result executeDynamic 결과
 * @returns {String} 업무처리번호 (없으면 빈 문자열)
 * @hidden N
 */
scwin.getRegisteredNo = function (result) {
    const body = scwin.getResBody(result);
    const list = body.bzProcsNoList;
    let no = "";

    if (Array.isArray(list)) {
        const first = list[0];
        no = (first !== null && typeof first === "object") ? (first.bzProcsNo ?? "") : (first ?? "");
    } else if (!$c.util.isEmpty(list)) {
        no = String(list).split(",")[0].trim();
    }
    return String(no || body.bzProcsNo || "");
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr 과 데이터셋 2개다. (§6.11)
 * @param {Number} row 대상 그리드 행
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function (row) {
    const isu = dlt_isuList.getRowJSON(row);

    // AS-IS fn_copy_dts(selectedGrdNum) → dts_Isu 1행
    const isuRow = {
        bzProcsNo : isu.bzProcsNo ?? "",
        isuCd : isu.isuCd ?? "",
        isuNm : isu.isuNm ?? "",
        isurCd : isu.isurCd ?? "",
        addYn : isu.addYn ?? ""
    };

    // AS-IS CopyDataSet(dts_Mst, param_dts_mst) + COM_NM = dts_Isu_Temp(selectedGrdNum).COM_NM
    const mstRow = { ...dma_detail.getJSON(), ...isuRow, comNm : isu.comNm ?? "" };

    return {
        formCd : scwin.DSCL_FORM_CD[scwin.secugrpId] ?? "",         // AS-IS arr[0] (EN 68392 / EF 99358)
        bzProcsNo : isu.bzProcsNo ?? "",                            // AS-IS arr[1] fr_bz_procs_no
        isurCd : isu.isurCd ?? "",                                  // AS-IS arr[2] Isur_cd
        mktId : scwin.DSCL_MKT_ID,                                  // AS-IS arr[3] '1'
        title : (scwin.secugrpId === scwin.SECUGRP_ID_EN) ? (isu.isuNm ?? "") : "",    // AS-IS arr[5] (ETN 종목명, ETF "")
        isu : [isuRow],                                             // AS-IS CopyDataSet(dts_Isu, param_dts_isu)
        mst : [mstRow]                                              // AS-IS CopyDataSet(dts_Mst, param_dts_mst)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성. 종목이 여럿이면 그리드에서 고른 행, 한 건이면 그 행을 대상으로 92024 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다.
 * 돌려받는 값은 없다. (원본 fn_dscl — §6.11, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    const rowCount = dlt_isuList.getRowCount();

    // ※TO-BE — 원본은 행이 없으면 빈 값으로 팝업을 열었다(§8 #11).
    if (rowCount === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (rowCount > 1 && scwin.selectedRow < 0) {
        await $c.win.alert("종목을 선택해 주세요.");
        return;
    }
    if (rowCount === 1) scwin.selectedRow = 0;

    scwin.dsclRow = scwin.selectedRow;

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 825,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #7)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData(scwin.dsclRow));
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 28
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.11, §10 #7, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [5] 제목 을 채운다([4] 는 원본도 비움)
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    if (scwin.dsclRow < 0) return arr.length;

    const data = scwin.getDsclData(scwin.dsclRow);

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[5] = data.title;        // 원본도 arr[4] 를 비운 채 arr[5] 를 채운다 — 92024 는 길이(≥5)로 본문 생성 여부를 가른다

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
